import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import { JobStore, type JobRecord } from './store.ts';

const db = openDatabase();
const store = new JobStore(db);
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY_BYTES = 64 * 1024;
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);

interface FieldError {
  field: string;
  message: string;
}

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  send(res, status, { error });
}

function invalid(res: ServerResponse, fields: FieldError[]): void {
  sendError(res, 400, 'invalid_request', 'The request is invalid.', fields);
}

function readBody(req: IncomingMessage): Promise<{ text: string } | { tooLarge: true }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) {
        tooLarge = true;
        return;
      }
      chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? { tooLarge: true } : { text: Buffer.concat(chunks).toString('utf8') }));
    req.on('error', reject);
  });
}

function isJsonContentType(value: string | undefined): boolean {
  return (value ?? '').split(';')[0]!.trim().toLowerCase() === 'application/json';
}

const isInt = (v: unknown, min: number, max: number): v is number => typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;

interface ValidJob {
  input: string;
  steps: number;
  failAttempts: number;
}

/** Validates the parsed body. Returns the job parameters with defaults applied, or the offending fields. */
function validateBody(obj: Record<string, unknown>): { ok: true; value: ValidJob } | { ok: false; fields: FieldError[] } {
  const fields: FieldError[] = [];
  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }

  const input = obj.input;
  if (typeof input !== 'string') fields.push({ field: 'input', message: 'is required and must be a string' });
  else if (input.length < 1 || input.length > 1000) fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
  else if (input.trim().length === 0) fields.push({ field: 'input', message: 'must not be only whitespace' });

  const steps = Object.hasOwn(obj, 'steps') ? obj.steps : 5;
  if (!isInt(steps, 1, 20)) fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });

  const failAttempts = Object.hasOwn(obj, 'failAttempts') ? obj.failAttempts : 0;
  if (!isInt(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input: input as string, steps: steps as number, failAttempts: failAttempts as number } };
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const fields: FieldError[] = [];

  const keyHeader = req.headers['idempotency-key'];
  let idempotencyKey: string | null = null;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && KEY_PATTERN.test(keyHeader)) idempotencyKey = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let parsed: unknown;
  let bodyReadable = false;
  const body = await readBody(req);
  if (!isJsonContentType(req.headers['content-type'])) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if ('tooLarge' in body) {
    fields.push({ field: 'body', message: 'body is too large' });
  } else {
    try {
      parsed = JSON.parse(body.text);
      bodyReadable = true;
    } catch {
      fields.push({ field: 'body', message: 'malformed JSON' });
    }
  }

  if (bodyReadable && (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed))) {
    fields.push({ field: 'body', message: 'must be a JSON object' });
    bodyReadable = false;
  }

  if (!bodyReadable) {
    invalid(res, fields);
    return;
  }

  const result = validateBody(parsed as Record<string, unknown>);
  if (!result.ok) {
    invalid(res, [...fields, ...result.fields]);
    return;
  }
  if (fields.length > 0) {
    invalid(res, fields);
    return;
  }

  const { input, steps, failAttempts } = result.value;
  const outcome = store.transaction((): { status: number; job?: JobRecord; conflict?: boolean } => {
    if (idempotencyKey !== null) {
      const existing = store.findByIdempotencyKey(idempotencyKey);
      if (existing) {
        const same = existing.input === input && existing.steps === steps && existing.failAttempts === failAttempts;
        return same ? { status: 200, job: existing } : { status: 409, conflict: true };
      }
    }
    return { status: 201, job: store.insertJob({ id: randomUUID(), input, steps, failAttempts, idempotencyKey }) };
  });

  if (outcome.conflict) {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, outcome.status, outcome.job);
}

function handle(req: IncomingMessage, res: ServerResponse): Promise<void> | void {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', `${method} is not allowed here.`);
    return send(res, 200, { status: 'ok', worker: store.isWorkerUp() ? 'up' : 'down' });
  }

  if (pathname === '/') {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', `${method} is not allowed here.`);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }

  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: store.listJobs() });
    if (method === 'POST') return createJob(req, res);
    return sendError(res, 405, 'method_not_allowed', `${method} is not allowed here.`);
  }

  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return sendError(res, 405, 'method_not_allowed', `${method} is not allowed here.`);
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    const job = store.getJob(id);
    if (!job) return sendError(res, 404, 'not_found', 'No such job.');
    return send(res, 200, job);
  }

  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  Promise.resolve()
    .then(() => handle(req, res))
    .catch((err: unknown) => {
      console.error('request failed', err);
      if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
      else res.end();
    });
});

const port = Number(process.env.PORT ?? 3000);
server.on('error', (err) => {
  console.error(`server error: ${err.message}`);
  process.exit(1);
});
server.listen(port, () => console.log(`server listening on ${port}`));

const shutdown = (): void => {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
};
process.once('SIGTERM', shutdown);
process.once('SIGINT', shutdown);

