import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase } from './db.ts';
import { JobStore, MAX_ATTEMPTS, RETRY_DELAY_MS, type JobRecord } from './store.ts';

/** Time for one step of processing. */
const STEP_MS = 100;
/** How long an idle worker waits before looking for queued work again. */
const IDLE_MS = 200;
const HEARTBEAT_MS = 1000;

const db = openDatabase();
const store = new JobStore(db);
let stopping = false;

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

async function runAttempt(job: JobRecord): Promise<void> {
  if (job.attempts <= job.failAttempts) {
    // Simulated transient failure: the attempt fails at its first step, before any progress.
    if (job.attempts >= MAX_ATTEMPTS) store.failJob(job.id, 'transient failure');
    else store.requeueJob(job.id, Date.now() + RETRY_DELAY_MS);
    return;
  }

  for (let completed = 1; completed <= job.steps; completed++) {
    await sleep(STEP_MS);
    if (stopping) {
      store.abortAttempt(job.id);
      return;
    }
    store.setProgress(job.id, completed);
  }
  store.completeJob(job.id, job.input.toUpperCase());
}

store.recoverInterrupted();
store.heartbeat();
const heartbeat = setInterval(() => store.heartbeat(), HEARTBEAT_MS);
console.log('worker started');

while (!stopping) {
  const job = store.claimNext();
  if (!job) {
    await sleep(IDLE_MS);
    continue;
  }
  await runAttempt(job);
}

clearInterval(heartbeat);
store.clearHeartbeat();
db.close();
console.log('worker stopped');

