import type { DatabaseSync, StatementSync } from 'node:sqlite';

/** Total processing attempts before a job is failed. */
export const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. */
export const RETRY_DELAY_MS = 500;
/** The worker counts as up if its heartbeat is at most this old. */
export const HEARTBEAT_TTL_MS = 3000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A job in the shape returned by the HTTP API. */
export interface JobRecord {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  run_after: number;
  created_at: string;
  updated_at: string;
}

const COLUMNS = 'seq, id, status, input, steps, fail_attempts, attempts, progress_completed, result_output, error, idempotency_key, run_after, created_at, updated_at';

function toRecord(r: JobRow): JobRecord {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' && r.result_output !== null ? { output: r.result_output } : null,
    error: r.error,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

const timestamp = (): string => new Date().toISOString();

type Param = string | number | null;

/** All SQL touching jobs. Used by both the server and the worker, each with its own connection. */
export class JobStore {
  private readonly statements = new Map<string, StatementSync>();

  constructor(private readonly db: DatabaseSync) {}

  private stmt(sql: string): StatementSync {
    let s = this.statements.get(sql);
    if (!s) {
      s = this.db.prepare(sql);
      this.statements.set(sql, s);
    }
    return s;
  }

  private one<T>(sql: string, ...params: Param[]): T | undefined {
    return this.stmt(sql).get(...params) as unknown as T | undefined;
  }

  /** Runs `fn` inside a write transaction; the lock is taken up front so no other writer can interleave. */
  transaction<T>(fn: () => T): T {
    this.db.exec('BEGIN IMMEDIATE');
    try {
      const out = fn();
      this.db.exec('COMMIT');
      return out;
    } catch (err) {
      this.db.exec('ROLLBACK');
      throw err;
    }
  }

  insertJob(job: { id: string; input: string; steps: number; failAttempts: number; idempotencyKey: string | null }): JobRecord {
    const now = timestamp();
    this.stmt(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
    ).run(job.id, job.input, job.steps, job.failAttempts, job.idempotencyKey, now, now);
    return this.getJob(job.id)!;
  }

  getJob(id: string): JobRecord | undefined {
    const row = this.one<JobRow>(`SELECT ${COLUMNS} FROM jobs WHERE id = ?`, id);
    return row && toRecord(row);
  }

  findByIdempotencyKey(key: string): JobRecord | undefined {
    const row = this.one<JobRow>(`SELECT ${COLUMNS} FROM jobs WHERE idempotency_key = ?`, key);
    return row && toRecord(row);
  }

  listJobs(): JobRecord[] {
    return (this.stmt(`SELECT ${COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[]).map(toRecord);
  }

  /** Worker: atomically moves the oldest due queued job to running and counts the new attempt. */
  claimNext(): JobRecord | undefined {
    return this.transaction(() => {
      const next = this.one<{ id: string }>(`SELECT id FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`, Date.now());
      if (!next) return undefined;
      this.stmt(`UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?`).run(
        timestamp(),
        next.id,
      );
      return this.getJob(next.id);
    });
  }

  /** Worker startup: any job left running belonged to a worker that died, so it is queued again. */
  recoverInterrupted(): void {
    this.stmt(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'`).run(timestamp());
  }

  setProgress(id: string, completed: number): void {
    this.stmt(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(completed, timestamp(), id);
  }

  completeJob(id: string, output: string): void {
    this.stmt(
      `UPDATE jobs SET status = 'completed', result_output = ?, error = NULL, progress_completed = steps, updated_at = ?
       WHERE id = ? AND status = 'running'`,
    ).run(output, timestamp(), id);
  }

  failJob(id: string, error: string): void {
    this.stmt(`UPDATE jobs SET status = 'failed', result_output = NULL, error = ?, progress_completed = 0, updated_at = ? WHERE id = ? AND status = 'running'`).run(
      error,
      timestamp(),
      id,
    );
  }

  requeueJob(id: string, runAfterMs: number): void {
    this.stmt(`UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'`).run(
      runAfterMs,
      timestamp(),
      id,
    );
  }

  /** Stopping mid-attempt: the attempt did not finish, so it is not counted and the job waits as queued. */
  abortAttempt(id: string): void {
    this.stmt(
      `UPDATE jobs SET status = 'queued', attempts = attempts - 1, progress_completed = 0, run_after = 0, updated_at = ? WHERE id = ? AND status = 'running'`,
    ).run(timestamp(), id);
  }

  heartbeat(nowMs: number = Date.now()): void {
    this.stmt(`INSERT INTO heartbeats (name, at) VALUES ('worker', ?) ON CONFLICT(name) DO UPDATE SET at = excluded.at`).run(nowMs);
  }

  clearHeartbeat(): void {
    this.stmt(`DELETE FROM heartbeats WHERE name = 'worker'`).run();
  }

  isWorkerUp(nowMs: number = Date.now()): boolean {
    const row = this.one<{ at: number }>(`SELECT at FROM heartbeats WHERE name = 'worker'`);
    return row !== undefined && nowMs - row.at <= HEARTBEAT_TTL_MS;
  }
}

